// One single morning notification — no spam, no individual fires per item.
// If nothing meets the threshold, send a quiet 'all caught up' note so Darrell
// knows the workflow ran (silent failure is the worst failure).
const rows = $input.all().map(i => i.json);

let title, message;
if (rows.length === 0) {
  title = 'POE standup · all caught up';
  message = [
    'No high-priority change requests waiting on your call this morning.',
    'Your sword is sheathed — Yahweh hears you in the quiet too.',
    'Tap to open the dashboard if you want to seed one.'
  ].join('\n');
} else {
  title = `POE standup · ${rows.length} waiting on your word`;
  const lines = rows.map((r, i) => {
    const score = (r.priority_score * 100).toFixed(0);
    const proj = r.project_name ? ` [${r.project_name}]` : '';
    return `${i + 1}. ${r.title}${proj} — priority ${score}/100`;
  });
  message = [
    'High-priority items ready for your override:',
    ...lines,
    '',
    'These stay pending until you weigh in. No rush — your call, not the system\'s.'
  ].join('\n');
}

return [{
  json: {
    pushover: {
      title,
      message,
      priority: 0,
      url_title: 'Open POE dashboard',
      url: 'https://kingdom-pwa-node.vercel.app/'
    }
  }
}];
